import{bQ as t,aL as a,u as o,G as n}from"./chunks/framework.igrrHzX3.js";const r="/knowledge/images/knowledge-overview.svg",s="/knowledge/images/rag-principle.svg",i="/knowledge/images/vectors-comparing-texts-meaning.svg",d="/knowledge/images/role-vector-db.svg",h="/knowledge/images/how-knowledge-works.svg",b=JSON.parse('{"title":"About","description":"","frontmatter":{},"headers":[],"relativePath":"about/introduction.md","filePath":"about/introduction.md"}'),l={name:"about/introduction.md"};function g(c,e,m,p,u,w){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h1><p><strong>knowledge</strong> is a <a href="https://www.ibm.com/fr-fr/think/topics/retrieval-augmented-generation" target="_blank" rel="noreferrer">retrieval-augmented generation (RAG)</a> engine specialised in the Kalisio ecosystem. It reads the <a href="https://kalisio.com/" target="_blank" rel="noreferrer">Kalisio</a> repositories, documentation, source code, DevOps configuration, cuts every file into passages along its own structure, turns each passage into a vector, and stores the vectors in a <a href="https://qdrant.tech/" target="_blank" rel="noreferrer">Qdrant</a> database.</p><p><img src="'+r+'" alt="knowledge at a glance"></p><h2 id="how-a-rag-works" tabindex="-1">How a RAG works <a class="header-anchor" href="#how-a-rag-works" aria-label="Permalink to &quot;How a RAG works&quot;">​</a></h2><p>A RAG runs in two phases: <strong>indexing</strong>, done once and then on every change of the corpus, and <strong>retrieval + generation</strong>, done on every question.</p><p><img src="'+s+'" alt="The two phases of a RAG"></p><h3 id="the-four-steps" tabindex="-1">The four steps <a class="header-anchor" href="#the-four-steps" aria-label="Permalink to &quot;The four steps&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Step</th><th>What it does</th><th>In knowledge</th></tr></thead><tbody><tr><td><strong>Ingestion</strong></td><td>Finds the documents, reads them, keeps the ones worth indexing</td><td><a href="/knowledge/guides/components/ingestion-job.html">Ingestion job</a></td></tr><tr><td><strong>Vectorisation</strong></td><td>Cuts each document into passages (<em>chunks</em>) and turns each one into a vector with an <em>embedding model</em></td><td><a href="/knowledge/guides/file-formats/">File formats</a> · <a href="/knowledge/guides/file-formats/#the-embedding-model">Embedding model</a></td></tr><tr><td><strong>Semantic search</strong></td><td>Turns the question into a vector with the same model and returns the nearest passage vectors</td><td><a href="/knowledge/guides/components/api.html#post-search-semantic-search-only"><code>/search</code></a> · <a href="/knowledge/guides/components/qdrant.html">Qdrant</a></td></tr><tr><td><strong>Generation</strong></td><td>Gives an LLM an instruction, the retrieved passages and the question, and returns what it writes</td><td><a href="/knowledge/guides/components/api.html#post-ask-retrieval-augmented-answer"><code>/ask</code></a></td></tr></tbody></table><h3 id="vectors-comparing-texts-by-their-meaning" tabindex="-1">Vectors: comparing texts by their meaning <a class="header-anchor" href="#vectors-comparing-texts-by-their-meaning" aria-label="Permalink to &quot;Vectors: comparing texts by their meaning&quot;">​</a></h3><p>An <strong>embedding model</strong> turns a text into a fixed-length list of numbers, 1 024 of them in knowledge, its coordinates in a <em>space of meaning</em>. The model is trained so that texts which mean the same thing land close together, whatever words they use, and, for a multilingual model, whatever language they are written in.</p><p><img src="'+i+'" alt="Vectors: comparing texts by their meaning"></p><h3 id="the-role-of-the-vector-database" tabindex="-1">The role of the vector database <a class="header-anchor" href="#the-role-of-the-vector-database" aria-label="Permalink to &quot;The role of the vector database&quot;">​</a></h3><p>Comparing a question with every passage one by one is fine for a thousand passages, too slow for millions. A <strong>vector database</strong> stores the vectors with their <em>payload</em> (the text, the file, the lines) and finds the nearest ones fast, with an approximate index, <a href="https://www.pinecone.io/learn/series/faiss/hnsw/" target="_blank" rel="noreferrer">HNSW</a> in Qdrant&#39;s case, a graph of vectors navigated from coarse to fine. It also filters on the payload, and lets the ingestion job update or delete the passages of a single file.</p><p><img src="'+d+'" alt="The role of the vector database"></p><h3 id="generation-the-llm-only-reads-what-it-is-given" tabindex="-1">Generation: the LLM only reads what it is given <a class="header-anchor" href="#generation-the-llm-only-reads-what-it-is-given" aria-label="Permalink to &quot;Generation: the LLM only reads what it is given&quot;">​</a></h3><p>The LLM does not search. It receives an instruction, the retrieved passages and the question, and writes the answer. A good answer therefore depends first on a good search.</p><table tabindex="0"><thead><tr><th>Piece</th><th>What it does</th></tr></thead><tbody><tr><td>Embedding model</td><td>turns a text into a vector</td></tr><tr><td>Vector database</td><td>finds the <em>k</em> nearest vectors</td></tr><tr><td>LLM</td><td>reads instruction + passages + question, writes the answer</td></tr></tbody></table><h2 id="how-knowledge-works" tabindex="-1">How knowledge works <a class="header-anchor" href="#how-knowledge-works" aria-label="Permalink to &quot;How knowledge works&quot;">​</a></h2><p>knowledge is that pipeline, cut into three components deployed apart:</p><p><img src="'+h+'" alt="How knowledge works"></p><ul><li>the <strong><a href="/knowledge/guides/components/ingestion-job.html">ingestion job</a></strong> clones the repositories, cuts every supported file along its structure, embeds the chunks with <a href="https://huggingface.co/Qwen/Qwen3-Embedding-0.6B" target="_blank" rel="noreferrer">Qwen3-Embedding-0.6B</a> and writes them to Qdrant, only what changed since the last run</li><li><strong><a href="/knowledge/guides/components/qdrant.html">Qdrant</a></strong> stores one point per chunk</li><li>the <strong><a href="/knowledge/guides/components/api.html">API</a></strong> embeds a question, and its translations, with the same model, searches Qdrant, and either returns the passages (<code>/search</code>) or has an LLM answer from them (<code>/ask</code>).</li></ul>',21)])])}const k=t(l,[["render",g]]);export{b as __pageData,k as default};
